SELECT

FROM TBL_PROJECT_INFO_REGISTER


        AND REGISTER_NO LIKE CONCAT('%', #{param.registerNo}, '%')


        AND PROJECT_NAME LIKE CONCAT('%', #{param.projectName}, '%')


        AND CONTRACTOR_FULL_NAME LIKE CONCAT('%', #{param.contractorFullName}, '%')


        AND CONTRACTOR_CREDIT_CODE = #{param.contractorCreditCode}


        AND FUNDING_SOURCE LIKE CONCAT('%', #{param.fundingSource}, '%')


        AND PROJECT_AMOUNT >= #{param.projectAmountMin}


        AND PROJECT_AMOUNT <= #{param.projectAmountMax}


        AND IS_FIRST_TALK_REPORT = #{param.isFirstTalkReport}


        AND REPORT_STATUS = #{param.reportStatus}


        AND PROJECT_STATUS = #{param.projectStatus}


        AND REGISTER_USER_NAME LIKE CONCAT('%', #{param.registerUserName}, '%')


        AND REGISTER_TIME >= #{param.registerTimeStart}


        AND REGISTER_TIME <= #{param.registerTimeEnd}


        AND CREATE_TIME >= #{param.createTimeStart}


        AND CREATE_TIME <= #{param.createTimeEnd}




        ORDER BY ${param.orderBy}

            ${param.orderDirection}



        ORDER BY CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_PROJECT_INFO_REGISTER


        AND REGISTER_NO LIKE CONCAT('%', #{param.registerNo}, '%')


        AND PROJECT_NAME LIKE CONCAT('%', #{param.projectName}, '%')


        AND CONTRACTOR_FULL_NAME LIKE CONCAT('%', #{param.contractorFullName}, '%')


        AND CONTRACTOR_CREDIT_CODE = #{param.contractorCreditCode}


        AND FUNDING_SOURCE LIKE CONCAT('%', #{param.fundingSource}, '%')


        AND PROJECT_AMOUNT >= #{param.projectAmountMin}


        AND PROJECT_AMOUNT <= #{param.projectAmountMax}


        AND IS_FIRST_TALK_REPORT = #{param.isFirstTalkReport}


        AND REPORT_STATUS = #{param.reportStatus}


        AND PROJECT_STATUS = #{param.projectStatus}


        AND REGISTER_USER_NAME LIKE CONCAT('%', #{param.registerUserName}, '%')


        AND REGISTER_TIME >= #{param.registerTimeStart}


        AND REGISTER_TIME <= #{param.registerTimeEnd}


        AND CREATE_TIME >= #{param.createTimeStart}


        AND CREATE_TIME <= #{param.createTimeEnd}

SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM TBL_PROJECT_INFO_REGISTER
WHERE REGISTER_NO = #{registerNo}

    AND PROJECT_ID != #{excludeProjectId}

SELECT

FROM TBL_PROJECT_INFO_REGISTER
WHERE PROJECT_NAME = #{projectName}
AND CONTRACTOR_FULL_NAME = #{contractorFullName}

    AND PROJECT_ID != #{excludeProjectId}

ORDER BY CREATE_TIME DESC
